        assert && items.forEach(item => {
            assert && assert(!item.tandemName || item.tandemName.endsWith(ITEM_TANDEM_NAME_SUFFIX), `ComboBoxItem tandemName must end with '${ITEM_TANDEM_NAME_SUFFIX}': ${item.tandemName}`);
        });
