            align: 'left',
            listPosition: 'below',
            disabledOpacity: 0.5,
            cornerRadius: 4,
            highlightFill: 'rgb( 245, 245, 245 )',
            xMargin: 12,
            yMargin: 8,
            // button
            buttonFill: 'white',
            buttonStroke: 'black',
            buttonLineWidth: 1,
            buttonTouchAreaXDilation: 0,
            buttonTouchAreaYDilation: 0,
            buttonMouseAreaXDilation: 0,
            buttonMouseAreaYDilation: 0,
            // list
            listFill: 'white',
            listStroke: 'black',
            listLineWidth: 1,
